func testFormaPagamentoToManyRemoveOpFrmpgtoChequeOcorenciaCheques(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a FormaPagamento
	var b, c, d, e ChequeOcorenciaCheque

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, formaPagamentoDBTypes, false, strmangle.SetComplement(formaPagamentoPrimaryKeyColumns, formaPagamentoColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ChequeOcorenciaCheque{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, chequeOcorenciaChequeDBTypes, false, strmangle.SetComplement(chequeOcorenciaChequePrimaryKeyColumns, chequeOcorenciaChequeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddFrmpgtoChequeOcorenciaCheques(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.FrmpgtoChequeOcorenciaCheques().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveFrmpgtoChequeOcorenciaCheques(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.FrmpgtoChequeOcorenciaCheques().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.FrmpgtoID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.FrmpgtoID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Frmpgto != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Frmpgto != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Frmpgto != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Frmpgto != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.FrmpgtoChequeOcorenciaCheques) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.FrmpgtoChequeOcorenciaCheques[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.FrmpgtoChequeOcorenciaCheques[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

