func testFormaPagamentoToOneEntidadeUsingEnt(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local FormaPagamento
	var foreign Entidade

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, formaPagamentoDBTypes, true, formaPagamentoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize FormaPagamento struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, entidadeDBTypes, false, entidadeColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Entidade struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.EntID, foreign.EntID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Ent().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.EntID, foreign.EntID) {
		t.Errorf("want: %v, got %v", foreign.EntID, check.EntID)
	}

	ranAfterSelectHook := false
	AddEntidadeHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Entidade) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := FormaPagamentoSlice{&local}
	if err = local.L.LoadEnt(ctx, tx, false, (*[]*FormaPagamento)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Ent == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Ent = nil
	if err = local.L.LoadEnt(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Ent == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

